@test("handlers run in order with the arguments")
def _():
    e, log = EventEmitter(), []
    e.on("msg", lambda x: log.append(("a", x)))
    e.on("msg", lambda x: log.append(("b", x)))
    assert e.emit("msg", 1) == 2
    assert log == [("a", 1), ("b", 1)], f"log = {log}"

@test("keyword arguments are passed through")
def _():
    e, got = EventEmitter(), {}
    e.on("save", lambda **kw: got.update(kw))
    e.emit("save", path="a.txt", force=True)
    assert got == {"path": "a.txt", "force": True}

@test("an unknown event calls nothing and returns 0")
def _():
    assert EventEmitter().emit("nothing") == 0

@test("once handlers run a single time")
def _():
    e, log = EventEmitter(), []
    e.once("ready", lambda: log.append("once"))
    e.on("ready", lambda: log.append("always"))
    e.emit("ready"); e.emit("ready")
    assert log == ["once", "always", "always"], f"log = {log}"

@test("off removes one registration; unknown is fine")
def _():
    e, log = EventEmitter(), []
    h = lambda: log.append("h")
    e.on("x", h); e.on("x", h)
    e.off("x", h)
    e.emit("x")
    assert log == ["h"], f"log = {log}"
    e.off("x", lambda: None)
    e.off("never", h)

@test("one failing handler doesn't stop the others")
def _():
    e, log = EventEmitter(), []
    def bad():
        raise ValueError("bad handler")
    e.on("go", bad)
    e.on("go", lambda: log.append("still ran"))
    err = raises(EmitError, e.emit, "go")
    assert log == ["still ran"]
    assert len(err.errors) == 1 and isinstance(err.errors[0], ValueError)

@test("changes during emit apply to the next emit")
def _():
    e, log = EventEmitter(), []
    def late():
        log.append("late")
    def second():
        log.append("second")
    def first():
        log.append("first")
        e.off("x", second)   # removed during emit: still runs this time
        e.on("x", late)      # added during emit: not called this time
    e.on("x", first)
    e.on("x", second)
    e.emit("x")
    assert log == ["first", "second"], f"first emit: {log}"
    log.clear()
    e.emit("x")
    assert log == ["first", "late"], f"second emit: {log}"

