class EmitError(Exception):
    def __init__(self, errors):
        super().__init__(f"{len(errors)} handler(s) failed")
        self.errors = errors


class EventEmitter:
    def __init__(self):
        self._handlers = {}  # event -> list of (handler, once) entries

    def on(self, event, handler):
        self._handlers.setdefault(event, []).append((handler, False))
        return handler

    def once(self, event, handler):
        self._handlers.setdefault(event, []).append((handler, True))
        return handler

    def off(self, event, handler):
        entries = self._handlers.get(event, [])
        for i, (h, _once) in enumerate(entries):
            if h == handler:
                del entries[i]
                return

    def _remove_entry(self, event, entry):
        entries = self._handlers.get(event, [])
        for i, e in enumerate(entries):
            if e is entry:
                del entries[i]
                return

    def emit(self, event, *args, **kwargs):
        snapshot = list(self._handlers.get(event, []))  # changes during emit don't affect this round
        errors = []
        for entry in snapshot:
            handler, once = entry
            if once:
                self._remove_entry(event, entry)
            try:
                handler(*args, **kwargs)
            except Exception as e:
                errors.append(e)
        if errors:
            raise EmitError(errors)
        return len(snapshot)
